const ZXMODS = {};
ZXMODS["checks"] = function (zx, sec) {
// Bridge self-check (same H1-H11 as the C1 hello panel) kept as a small collapsed module so the owner can re-verify after any UI update.
sec.innerHTML = '<details><summary>BRIDGE SELF-CHECK</summary><div class="row"><button id="bRun">RUN TESTS</button><button id="bCopy" class="alt">COPY REPORT</button></div><pre id="out">tap RUN TESTS</pre></details>';
const out = sec.querySelector('#out'); const lines = []; let head = 'UI C1 REPORT: not run';
const paint = () => { out.textContent = head + '\n' + lines.join('\n'); };
const add = (id, ok, note) => { lines.push('[' + (ok ? 'PASS' : 'FAIL') + '] ' + id + ' ' + note); paint(); return ok; };
const refused = async (fn, code) => { try { await fn(); return 'was NOT refused'; } catch (e) { return e && e.code === code ? '' : 'wrong error: ' + (e && e.code) + ' ' + (e && e.message); } };
async function runTests() {
  lines.length = 0; head = 'UI C1 REPORT: running'; paint();
  let pass = 0, fail = 0; const r = (ok) => { if (ok) pass++; else fail++; };
  r(add('H1', true, 'sandbox ui mounted, new Function ran this code, origin=' + (location.origin || 'null')));
  r(add('H2', typeof chrome === 'undefined' || !chrome.runtime || !chrome.runtime.id, 'no chrome.* inside the sandbox'));
  try { const m = await zx.getManifest(); r(add('H3', !!m.version, 'manifest ' + m.name + ' ' + m.version + ' shellApi ' + m.shellApi)); } catch (e) { r(add('H3', false, String(e.message))); }
  try { const ts = []; for (let i = 0; i < 20; i++) { const t = performance.now(); await zx.ping(); ts.push(performance.now() - t); } const avg = ts.reduce((a, b) => a + b, 0) / ts.length; r(add('H4', avg < 30, 'bridge RTT avg ' + avg.toFixed(1) + ' ms, max ' + Math.max.apply(null, ts).toFixed(1) + ' ms (goal <30)')); } catch (e) { r(add('H4', false, String(e.message))); }
  try { const v = 'v' + Date.now(); await zx.storage.set({ zex_ui_hello_probe: v }); const g = await zx.storage.get(['zex_ui_hello_probe']); await zx.storage.remove(['zex_ui_hello_probe']); r(add('H5', g.zex_ui_hello_probe === v, 'storage set/get/remove round-trip')); } catch (e) { r(add('H5', false, String(e.message))); }
  let x;
  x = await refused(() => zx.storage.get(['zauth_session']), 'secret_key'); r(add('H6', !x, 'secret key read refused ' + x));
  x = await refused(() => zx.storage.set({ my_api_key: 'x' }), 'secret_key'); r(add('H7', !x, 'secret key write refused ' + x));
  x = await refused(() => zx.storage.set({ zex_sbx_remote_floors: {} }), 'own_key'); r(add('H8', !x, 'update-machinery write refused ' + x));
  x = await refused(() => zx.runtime.sendMessage({ type: 'zexTest', payload: { apiKey: 'k' } }), 'secret_key'); r(add('H9', !x, 'message with secret key refused ' + x));
  x = await refused(() => zx.tabs.create('https://example.org/'), 'tab_not_allowed'); r(add('H10', !x, 'non X/Telegram tab refused ' + x));
  try { const t = await zx.tabs.query(); r(add('H11', Array.isArray(t), 'tabs.query returns only X/Telegram tabs (' + t.length + ' open)')); } catch (e) { r(add('H11', false, String(e.message))); }
  head = 'UI C1 REPORT: ' + (fail ? 'FAIL' : 'ALL PASS') + ' (' + pass + ' pass, ' + fail + ' fail)\ntime: ' + new Date().toISOString(); paint();
}
sec.querySelector('#bRun').onclick = runTests;
sec.querySelector('#bCopy').onclick = async () => { try { await zx.clipboard.write(out.textContent); lines.push('(report copied)'); } catch (e) { lines.push('copy failed: ' + e.message); } paint(); };

};
ZXMODS["switches"] = function (zx, sec) {
// C2a: SANDBOX / AUTO-UPDATE BRAIN / SANDBOX UI / DRY-RUN / BRAIN GATE / HUMAN MODE. Same storage keys + messages as popup_classic (popup.js sandboxUi()).
const KEYS = ['zex_sandbox_enabled', 'zex_sbx_status', 'zex_sbx_remote_on', 'zex_sbx_remote_info', 'zex_sbx_comp_status', 'zex_ui_sandbox_on', 'zex_dryrun', 'zex_brain_gate', 'zex_human'];
const S = {}; let note = '', unote = '';
const SW = [
  { id: 'sbx', t: 'SANDBOX', k: 'zex_sandbox_enabled' },
  { id: 'upd', t: 'AUTO-UPDATE BRAIN', k: 'zex_sbx_remote_on' },
  { id: 'ui', t: 'SANDBOX UI (TEST)', k: 'zex_ui_sandbox_on' },
  { id: 'dry', t: 'DRY-RUN (REP ONLY)', k: 'zex_dryrun' },
  { id: 'gate', t: 'BRAIN GATE', k: 'zex_brain_gate' },
  { id: 'hum', t: 'HUMAN MODE', k: 'zex_human' },
];
sec.innerHTML = '<h2>SWITCHES</h2>' + SW.map((s) =>
  '<div class="sw"><div class="info"><div class="t">' + s.t + '</div><div class="d" id="d_' + s.id + '">…</div></div>' +
  (s.id === 'upd' ? '<button class="alt sm" id="bNow" style="display:none">CHECK NOW</button>' : '') +
  '<label class="tg"><input type="checkbox" id="c_' + s.id + '"><i></i></label></div>' +
  (s.id === 'sbx' ? '<div class="row" id="tools" style="display:none"><button class="alt" id="bTest">SELF-TEST</button><button class="alt" id="bRestart">RESTART</button><button class="alt" id="bLog">COPY LOG</button></div>' : '') +
  (s.id === 'upd' ? '<div class="comp" id="comp"></div>' : '')).join('');
const q = (id) => sec.querySelector('#' + id);
const on = (k) => S[k] === true;
const D = {
  sbx: () => { if (!on('zex_sandbox_enabled')) return 'OFF'; if (note) return note; const st = S.zex_sbx_status, s = (st && st.state) || 'starting'; return 'ON — ' + (s === 'ready' ? 'brain ready' + (st.rttMs != null ? ' (' + st.rttMs + ' ms)' : '') : s === 'failed' ? 'failed: ' + (st.lastError || '?') : s === 'starting' ? 'starting…' : s) + (st && st.restarts ? ' · restarts ' + st.restarts : ''); },
  upd: () => { if (unote) return unote; if (!on('zex_sbx_remote_on')) return 'OFF — only the brain inside this zip runs'; const info = S.zex_sbx_remote_info, st = S.zex_sbx_status; return 'ON — gets new brains signed by you' + (info ? ' · ' + (info.ok ? '' : '⚠ ') + info.msg + ' (' + new Date(info.t).toLocaleTimeString() + ')' : '') + (st && st.src ? ' · running ' + st.src + ' ' + (st.bundle || '') : ''); },
  ui: () => on('zex_ui_sandbox_on') ? 'ON — popup loads the downloaded UI (needs AUTO-UPDATE ON); the classic popup stays the fallback' : 'OFF — the classic popup opens',
  dry: () => on('zex_dryrun') ? 'ON — Comment REP drafts the reply but posts NOTHING (AI credits are still used)' : 'OFF',
  gate: () => on('zex_brain_gate') ? 'ON — brain decides skip / blacklist / Wallchain for REP (needs SANDBOX ON; local code is the fallback)' : 'OFF — local code decides (brain only double-checks)',
  hum: () => on('zex_human') ? 'ON — random click point, bell-curve gaps, rest break every 8-14 replies, slows down with fatigue and after X errors, one tab clicks at a time (not in Flash)' : 'OFF — normal timing',
};
function paint() {
  SW.forEach((s) => { q('c_' + s.id).checked = on(s.k); q('d_' + s.id).textContent = D[s.id](); });
  q('tools').style.display = on('zex_sandbox_enabled') ? 'flex' : 'none';
  q('bNow').style.display = on('zex_sbx_remote_on') ? 'inline-block' : 'none';
  const cs = S.zex_sbx_comp_status || {};
  q('comp').textContent = ['brain', 'ui', 'hands'].map((n) => cs[n] ? n + ' ' + cs[n].ver + ' ' + cs[n].src + (cs[n].note ? ' (' + cs[n].note + ')' : '') : n + ' —').join(' · ');
}
const say = (t) => { note = t; paint(); setTimeout(() => { note = ''; paint(); }, 6000); };
SW.forEach((s) => {
  q('c_' + s.id).addEventListener('change', (e) => {
    const v = e.target.checked, was = S[s.k]; S[s.k] = v; if (s.id === 'sbx') note = ''; paint();
    zx.storage.set({ [s.k]: v }).catch((x) => { S[s.k] = was; paint(); q('d_' + s.id).textContent = 'could not save: ' + x.message; });
  });
});
q('bNow').onclick = () => {
  unote = 'checking…'; paint();
  zx.runtime.sendMessage({ type: 'zexSandbox', cmd: 'update' }).then((r) => { unote = (r && r.msg) || 'no answer (is SANDBOX ON?)'; }, (x) => { unote = 'failed: ' + x.message; }).then(() => { paint(); setTimeout(() => { unote = ''; paint(); }, 6000); });
};
q('bTest').onclick = () => {
  say('testing…');
  zx.runtime.sendMessage({ type: 'zexUi', payload: { cmd: 'selftest' } }).then((r) => {
    if (!r || !r.ok) return say('test failed: ' + ((r && r.error) || 'no answer'));
    const bad = (r.data.checks || []).filter((c) => !c.ok).map((c) => c.name);
    say('self-test ' + r.data.passed + '/' + r.data.total + (bad.length ? ' — FAIL: ' + bad.join(', ') : ' — all OK'));
  }, (x) => say('test failed: ' + x.message));
};
q('bRestart').onclick = () => { say('restarting…'); zx.runtime.sendMessage({ type: 'zexSandbox', cmd: 'restart' }).catch(() => {}); };
q('bLog').onclick = async () => {
  try {
    const log = await zx.runtime.sendMessage({ type: 'zexSandbox', cmd: 'log' });
    const bs = await zx.runtime.sendMessage({ type: 'zexUi', payload: { cmd: 'rep.stats' } }).catch(() => null);   // what the brain really decided so far
    await zx.clipboard.write(JSON.stringify({ status: S.zex_sbx_status || null, brain: (bs && bs.ok) ? bs.data : null, log: log || [] }, null, 1));
    say('log copied');
  } catch (x) { say('copy failed: ' + x.message); }
};
zx.storage.onChanged((ch) => { let hit = false; KEYS.forEach((k) => { if (ch[k]) { S[k] = ch[k].newValue; hit = true; if (k === 'zex_sandbox_enabled') note = ''; } }); if (hit) paint(); });
paint();
return zx.storage.get(KEYS).then((d) => { KEYS.forEach((k) => { if (k in d) S[k] = d[k]; }); paint(); });

};
// Z EX main UI (C2). Modules are registered by tools/build_ui.mjs as ZXMODS[name] = function (zx, sec). One crashing module never takes the others down.
const order = ['switches', 'checks'];
const host = root.querySelector('#mods');
const showErr = (sec, n, e) => { const d = document.createElement('div'); d.className = 'err'; d.textContent = 'module "' + n + '" failed: ' + String((e && e.message) || e); sec.appendChild(d); try { zx.log('module ' + n + ' failed: ' + ((e && e.message) || e)); } catch (x) { /* ignore */ } };
order.forEach((n) => {
  const sec = document.createElement('section'); sec.className = 'mod'; sec.setAttribute('data-mod', n); host.appendChild(sec);
  try { const r = ZXMODS[n](zx, sec); if (r && typeof r.then === 'function') r.catch((e) => showErr(sec, n, e)); } catch (e) { showErr(sec, n, e); }
});
root.querySelector('#bClassic').onclick = () => zx.classic();
zx.getManifest().then((m) => { root.querySelector('#ver').textContent = m.name + ' ' + m.version + ' · main ui 1.1.0 · modules: ' + order.join(', '); }).catch(() => {});
